import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

describe('ChatOrchestrator onError for Error rejections', () => {
  // spec: specs/hal-engine-config-hooks/spec.md#4
  it('passes the original Error instance to onError and rethrows it unchanged', async () => {
    const reason = new Error('provider failed');
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw reason;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const session: ChatSession = {
      sessionId: 'test-session',
      userId: 'user-1',
      entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
    };
    let hookError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        hookError = error;
      },
    };
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {hooks});
    let callerError: unknown;
    try {
      await orchestrator.processMessage(session);
    } catch (error) {
      callerError = error;
    }

    expect({hookError, callerError}).toEqual({hookError: reason, callerError: reason});
  });
});
